sequenceDiagram(name = "CheckoutProcess") {
    val customer = lifeline(name = "Customer") { isActor = true }
    val shop = lifeline(name = "Shop")
    val paymentGateway = lifeline(name = "Payment Gateway")
    val database = lifeline(name = "Database")
    message(from = customer, to = shop, label = "initiateCheckout()")
    message(from = shop, to = paymentGateway, label = "verifyPaymentDetails()")
    alt(isPaymentValid = true) {
        message(from = paymentGateway, to = shop, label = "paymentVerified")
        message(from = shop, to = database, label = "saveOrder()")
        message(from = database, to = shop, label = "orderSaved")
        message(from = shop, to = paymentGateway, label = "processPayment()")
        message(from = paymentGateway, to = shop, label = "paymentProcessed")
    } else {
        message(from = paymentGateway, to = shop, label = "paymentInvalid")
    }
    message(from = shop, to = customer, label = "displayResult()")
}

sequenceDiagram(name  =  "Order Process")  {
    val customer  = lifeline(name  =  "Customer")  { isActor  = true  }
    val orderService  = lifeline(name  =  "Order Service")
    val orchestrator  = lifeline(name  =  "Saga Orchestrator")
    val warehouseService  = lifeline(name  =  "Warehouse Service")
    val paymentService  = lifeline(name  =  "Payment Service")
    val shipmentService  = lifeline(name  =  "Shipment Service")
    val eventLog  = lifeline(name  =  "Event Log")

    message(from  = customer, to  = orderService, label  =  "placeOrder()")
    message(from  = orderService, to  = orchestrator, label  =  "createOrchestrator()")
    message(from  = orchestrator, to  = warehouseService, label  =  "reserveItems()")
    reply(from  = warehouseService, to  = orchestrator, label  =  "reservationResult")

    alt(reservationResult  ==  "success")  {
        message(from  = orchestrator, to  = paymentService, label  =  "executePayment()")
        reply(from  = paymentService, to  = orchestrator, label  =  "paymentResult")
        alt(paymentResult  ==  "success")  {
            message(from  = orchestrator, to  = shipmentService, label  =  "commissionShipment()")
            reply(from  = shipmentService, to  = orchestrator, label  =  "shipmentResult")
            message(from  = orchestrator, to  = eventLog, label  =  "logStep(shipmentResult)")
        }  else  {
            message(from  = orchestrator, to  = warehouseService, label  =  "cancelReservation()")
            reply(from  = warehouseService, to  = orchestrator, label  =  "cancellationResult")
            message(from  = orchestrator, to  = eventLog, label  =  "logStep(cancellationResult)")
        }
    }  else  {
        message(from  = orchestrator, to  = eventLog, label  =  "logStep(aborted)")
    }

    message(from  = orchestrator, to  = orderService, label  =  "orderStatus()")
    reply(from  = orderService, to  = customer, label  =  "orderStatusResult")
}

sequenceDiagram(name  =  "Login Flow")  {
    val clientApp  = lifeline(name  =  "Client Application")  { isActor  = true  }
    val authServer  = lifeline(name  =  "Authorization Server")
    val sessionStore  = lifeline(name  =  "Session Store")
    val resourceServer  = lifeline(name  =  "Resource Server")
    val auditLog  = lifeline(name  =  "Audit Log")

    message(from  = clientApp, to  = authServer, label  =  "initiates login")
    message(from  = authServer, to  = clientApp, label  =  "redirects to login form")

    message(from  = clientApp, to  = authServer, label  =  "submits credentials")
    message(from  = authServer, to  = sessionStore, label  =  "creates new session")

    alt(credValid  =  "credentials valid")  {
        message(from  = authServer, to  = authServer, label  =  "verifies credentials")
        message(from  = authServer, to  = clientApp, label  =  "issues authorization code")
        message(from  = clientApp, to  = authServer, label  =  "exchanges code for access token")
        message(from  = authServer, to  = auditLog, label  =  "notes issuance in audit log")

        alt(requestsProfile  =  "requested scope includes profile")  {
            message(from  = clientApp, to  = authServer, label  =  "requests user data with token")
            message(from  = authServer, to  = resourceServer, label  =  "re-verifies token")
            message(from  = resourceServer, to  = authServer, label  =  "releases user data")
            message(from  = authServer, to  = clientApp, label  =  "delivers user data")
        }
    }
    else(credInvalid  =  "credentials invalid")  {
        message(from  = authServer, to  = sessionStore, label  =  "discards session")
        message(from  = authServer, to  = clientApp, label  =  "shows error message")
    }
}

sequenceDiagram(name = "SensorFusion") {
    val sensor1 = lifeline(name = "Camera Sensor") { isActor = true }
    val sensor2 = lifeline(name = "Radar Sensor") { isActor = true }
    val fusionUnit = lifeline(name = "Fusion Unit")
    val emergencyBrakingAssistant = lifeline(name = "Emergency Braking Assistant")
    val controlUnit = lifeline(name = "Control Unit")
    val diagnosticLog = lifeline(name = "Diagnostic Log")
    val driver = lifeline(name = "Driver")
    message(from = sensor1, to = fusionUnit, label = "measurement data")
    message(from = sensor2, to = fusionUnit, label = "measurement data")
    message(from = fusionUnit, to = emergencyBrakingAssistant, label = "collision risk with time-to-collision")
    alt(risk < threshold) {
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "initiate autonomous braking")
        while(controlUnit.adjustingBrakePressure) {
            message(from = controlUnit, to = emergencyBrakingAssistant, label = "brake pressure adjustment")
        }
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "end maneuver")
        message(from = emergencyBrakingAssistant, to = diagnosticLog, label = "record event")
    } else {
        message(from = emergencyBrakingAssistant, to = driver, label = "distance warning")
        message(from = emergencyBrakingAssistant, to = diagnosticLog, label = "log observed risk")
    }
}

